TickType_t ux_Task_Reset_Event_شي_قدر( فراغ )
{
    TickType_t uxReturn;

    trace_ENTER_ux_Task_Reset_Event_شي_قدر();

    uxReturn = list_GET_LIST_شي_قدر( &( pxCurrentTCB->x_Event_List_شي ) );

    /* Reset the event list item to its normal value - so it can be used with
     * queues and semaphores. */
    list_سيٽ_LIST_شي_قدر( &( pxCurrentTCB->x_Event_List_شي ), ( ( TickType_t ) configMAX_PRIORITIES - ( TickType_t ) pxCurrentTCB->ux_ترجيح ) );

    trace_RETURN_ux_Task_Reset_Event_شي_قدر( uxReturn );

    أرجع uxReturn;
}
